<?php
function coExportRows(CoService $s,$company,$report,array $p){$r=new CoReports($s);$methods=['journal'=>'journal','ledger'=>'ledger','trial'=>'trial','auxiliary'=>'auxiliary','comparative'=>'comparative','annual'=>'annual'];if(isset($methods[$report]))return $r->{$methods[$report]}($company,$p);if(in_array($report,['sales','purchases'],true))return array_values(array_filter($r->tax($company,$p)['documents'],function($d)use($report){return $d['Kind']===($report==='sales'?'sale':'purchase');}));if($report==='cash'){$rows=$r->journal($company,$p);$codes=[];foreach($s->accountRows($company) as $a)if(in_array($a['ReportGroup'],['cash','bank'],true))$codes[]=$a['Code'];return array_values(array_filter($rows,function($l)use($codes){return in_array($l['Account'],$codes,true);}));}if($report==='statements'){$data=$r->statements($company,$p);$rows=[];foreach($data['groups'] as $g)$rows[]=['Estado'=>'Rubros contables','Rubro'=>$g['group'],'Inicial'=>$g['opening'],'Movimiento'=>$g['movement'],'Final'=>$g['balance']];foreach(['position'=>'Situación financiera','results'=>'Resultados','equity'=>'Cambios en el patrimonio'] as $section=>$label)foreach($data[$section] as $key=>$value)$rows[]=['Estado'=>$label,'Rubro'=>$key,'Inicial'=>null,'Movimiento'=>null,'Final'=>$value];$rows[]=['Estado'=>'Flujos de efectivo','Rubro'=>'Saldo inicial','Inicial'=>$data['cashFlow']['opening'],'Movimiento'=>null,'Final'=>null];foreach($data['cashFlow']['flows'] as $key=>$value)$rows[]=['Estado'=>'Flujos de efectivo','Rubro'=>$key,'Inicial'=>null,'Movimiento'=>$value,'Final'=>null];$rows[]=['Estado'=>'Flujos de efectivo','Rubro'=>'Saldo final','Inicial'=>null,'Movimiento'=>null,'Final'=>$data['cashFlow']['closing']];return $rows;}throw new InvalidArgumentException('Reporte inválido.');}
function coExport(CoService $s,$company,$report,$format,array $p){
 $c=$s->permit($company,'export');$rows=coExportRows($s,$company,$report,$p);if(count($rows)>50000)throw new InvalidArgumentException('Reduce el rango para exportar.');
 $s->transaction(function()use($s,$company,$report,$format,$p,$rows){$s->audit($company,'export','report',$report,['format'=>$format,'filters'=>$p,'rows'=>count($rows)]);});
 $selection=['trial'=>['Code','Name','OpeningDebit','OpeningCredit','Debit','Credit','Balance'],'journal'=>['EntryDate','Number','Document','Account','AccountName','Debit','Credit','Currency','SourceId'],'ledger'=>['Account','AccountName','EntryDate','Document','Debit','Credit','RunningBalance'],'sales'=>['IssueDate','DocType','Series','DocNumber','PartyDoc','PartyName','Taxable','Exempt','Unaffected','FreeAmount','FreeIgv','Igv','Total','State'],'purchases'=>['IssueDate','DocType','Series','DocNumber','PartyDoc','PartyName','Taxable','Exempt','Unaffected','FreeAmount','FreeIgv','Igv','Total','State'],'cash'=>['EntryDate','Document','Account','Debit','Credit','CashFlow'],'auxiliary'=>['Account','PartyType','PartyId','OpeningDebit','OpeningCredit','Debit','Credit','Balance']];
 if(isset($selection[$report]))foreach($rows as &$row)$row=array_intersect_key($row,array_flip($selection[$report]));unset($row);
 $titles=['trial'=>'Balance de comprobación','journal'=>'Libro diario','ledger'=>'Libro mayor','sales'=>'Registro de ventas','purchases'=>'Registro de compras','cash'=>'Caja y bancos','auxiliary'=>'Libros auxiliares','statements'=>'Estados financieros','comparative'=>'Comparativo mensual','annual'=>'Comparativo anual'];$title=$titles[$report]??$report;
 $labels=['Code'=>'Código','Name'=>'Cuenta contable','OpeningDebit'=>'Debe inicial S/','OpeningCredit'=>'Haber inicial S/','Debit'=>'Debe S/','Credit'=>'Haber S/','Balance'=>'Saldo S/','RunningBalance'=>'Acumulado S/','EntryDate'=>'Fecha','Number'=>'N°','Document'=>'Documento','Account'=>'Cuenta','AccountName'=>'Cuenta contable','Currency'=>'Moneda','SourceId'=>'Origen','IssueDate'=>'Emisión','DocType'=>'Tipo','Series'=>'Serie','DocNumber'=>'Número','PartyDoc'=>'Documento tercero','PartyName'=>'Tercero','Taxable'=>'Base gravada S/','Exempt'=>'Exonerado S/','Unaffected'=>'Inafecto S/','FreeAmount'=>'Valor gratuito S/','FreeIgv'=>'IGV gratuito S/','Igv'=>'IGV S/','Total'=>'Total S/','State'=>'Estado','PartyType'=>'Tipo tercero','PartyId'=>'ID tercero','CashFlow'=>'Flujo'];
 $columns=count($rows)?array_keys($rows[0]):['Sin movimientos'];$headers=array_map(function($key)use($labels){return $labels[$key]??$key;},$columns);$money=['Debit','Credit','OriginalDebit','OriginalCredit','OpeningDebit','OpeningCredit','Balance','RunningBalance','Taxable','Exempt','Unaffected','FreeAmount','FreeIgv','Igv','OtherTaxes','Total','Withholding','Perception','Detraction','income','expenses','net','assets','liabilities','equity','Inicial','Movimiento','Final'];
 foreach($rows as &$row)foreach($row as $k=>&$v){if(in_array($k,$money,true))$v=$v===null?'':coAmount((int)$v);elseif(is_array($v))$v=coJson($v);}unset($row,$v);
 if($format==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="contabilidad-'.$report.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$headers);foreach($rows as $row){foreach($row as &$v)if(is_string($v)&&preg_match('/^\s*[=+@\-\t\r]/',$v)&&!preg_match('/^-?\d+(?:\.\d+)?$/',$v))$v="'".$v;unset($v);fputcsv($out,$row);}fclose($out);return;}
 if($format==='xlsx'){
  if(!class_exists('\PhpOffice\PhpSpreadsheet\Spreadsheet'))require_once __DIR__.'/vendor/autoload.php';$book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();$sheet->setTitle('Contabilidad');$sheet->setCellValue('A1',$c['Name'].' · '.$c['Ruc']);$sheet->setCellValue('A2',$title.' | '.($p['from']??'').' a '.($p['to']??'').' | Moneda funcional PEN');
  foreach($headers as $i=>$name)$sheet->setCellValueByColumnAndRow($i+1,4,$name);foreach($rows as $i=>$row){$col=1;foreach($row as $key=>$value){$cell=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($col).($i+5);if(in_array($key,$money,true)&&$value!==''){$sheet->setCellValueExplicit($cell,(float)$value,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_NUMERIC);$sheet->getStyle($cell)->getNumberFormat()->setFormatCode('#,##0.00;[Red]-#,##0.00');}else $sheet->setCellValueExplicit($cell,(string)$value,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);$col++;}}
  $last=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(count($columns));$sheet->getStyle('A4:'.$last.'4')->getFont()->setBold(true)->getColor()->setARGB('FFFFFFFF');$sheet->getStyle('A4:'.$last.'4')->getFill()->setFillType('solid')->getStartColor()->setARGB('FF174B62');$sheet->freezePane('A5');$sheet->setAutoFilter('A4:'.$last.max(4,count($rows)+4));for($i=1;$i<=count($columns);$i++)$sheet->getColumnDimension(\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($i))->setWidth(in_array($columns[$i-1],['Memo','AccountName','Name','PartyName','Rubro'],true)?40:20);$sheet->getStyle('A1:'.$last.max(5,count($rows)+4))->getAlignment()->setVertical('top')->setWrapText(true);
  header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="contabilidad-'.$report.'.xlsx"');(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');return;
 }
 if($format==='pdf'){
  if(!class_exists('TCPDF'))require_once __DIR__.'/sunat/plugins/tcpdf/tcpdf.php';$pdf=new TCPDF('L','mm',count($columns)>10?'A3':'A4',true,'UTF-8',false);$pdf->SetCreator('NEUROSOFT');$pdf->SetTitle('Contabilidad '.$report);$pdf->setPrintHeader(false);$pdf->setPrintFooter(true);$pdf->SetMargins(8,10,8);$pdf->AddPage();$pdf->SetFont('helvetica','',9);$esc=function($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');};$html='<h2>'.$esc($c['Name']).' · '.$esc($title).'</h2><p>RUC '.$esc($c['Ruc']).' | '.$esc($p['from']??'').' a '.$esc($p['to']??'').' | Moneda funcional PEN</p><table border="1" cellpadding="3"><thead><tr>';foreach($headers as $col)$html.='<th bgcolor="#e4f0f4">'.$esc($col).'</th>';$html.='</tr></thead><tbody>';foreach($rows as $row){$html.='<tr>';foreach($row as $value)$html.='<td>'.$esc($value).'</td>';$html.='</tr>';}$html.='</tbody></table>';$pdf->writeHTML($html);$pdf->Output('contabilidad-'.$report.'.pdf','I');return;
 }throw new InvalidArgumentException('Formato no disponible.');
}
// PLE diary, current-period movements only. Uses official 21 mandatory fields (RS 169-2015).
// Previous-period corrections, opening/closing and structured register links require explicit metadata, never inferred.
function coPleDiary(CoService $s,$company,array $p){$c=$s->permit($company,'export');$period=coPeriod($p['period']??'');if($c['Obligation']!=='ple')throw new InvalidArgumentException('La empresa no está configurada para PLE.');if(empty($c['settings']['taxReviewed']))throw new InvalidArgumentException('El contador debe revisar la configuración tributaria antes de exportar PLE.');$state=$s->one("SELECT * FROM Co_Period WHERE CompanyId=? AND Period=? AND State='closed'",[$company,$period]);if(!$state)throw new InvalidArgumentException('Cierra y revisa el período antes de exportar el libro electrónico.');$rows=(new CoReports($s))->journal($company,['from'=>$period.'-01','to'=>(new DateTime($period.'-01'))->format('Y-m-t')]);$out=[];
 foreach($rows as $r){$tax=$s->one('SELECT * FROM Co_TaxDocument WHERE CompanyId=? AND EntryId=?',[$company,$r['Id']]);if($tax){$input=json_decode($tax['OriginalData'],true);$meta=['issuerType'=>'6','issuerDoc'=>$tax['Kind']==='sale'?$c['Ruc']:$tax['PartyDoc'],'docType'=>$tax['DocType'],'series'=>$tax['Series'],'number'=>$tax['DocNumber'],'reference'=>$input['pleReference']??''];if($meta['reference']==='')throw new InvalidArgumentException('Falta referencia revisada al registro del asiento #'.$r['Id']);}else{$meta=empty($r['ElectronicData'])?null:coElectronic(json_decode($r['ElectronicData'],true));if(!$meta)throw new InvalidArgumentException('Faltan metadatos electrónicos del asiento #'.$r['Id']);}$ref=$meta['reference'];$clean=function($v){return str_replace(["|","\r","\n"],[' ',' ',' '],(string)$v);};$dt=(new DateTime($r['EntryDate']))->format('d/m/Y');$issuer=$meta['issuerDoc'];$fields=[str_replace('-','',$period).'00','CO'.$r['Id'],($r['SourceType']==='opening'?'A':($r['SourceType']==='closing'?'C':'M')).$r['LineId'],$r['Account'],$r['BranchId']??'','',$r['Currency'],$meta['issuerType'],$issuer,$meta['docType'],$meta['series'],$meta['number'],$dt,'',$dt,mb_substr($r['Memo'],0,200),'',coAmount((int)$r['Debit']),coAmount((int)$r['Credit']),$ref,'1'];$out[]=implode('|',array_map($clean,$fields)).'|';}
 $s->transaction(function()use($s,$company,$period,$rows){$s->audit($company,'export','ple-050100',$period,['rows'=>count($rows)]);});return ['name'=>'LE'.$c['Ruc'].str_replace('-','',$period).'00050100001'.(count($rows)?'1':'0').'11.txt','text'=>implode("\r\n",$out).(count($out)?"\r\n":'')];}
